  db.prepare('INSERT INTO heartbeats (name, at_ms) VALUES (?, ?) ON CONFLICT(name) DO UPDATE SET at_ms = excluded.at_ms').run(name, atMs);
}

export function readHeartbeat(db: DatabaseSync, name: string): number | undefined {
  const row = db.prepare('SELECT at_ms FROM heartbeats WHERE name = ?').get(name) as unknown as { at_ms: number } | undefined;
  return row?.at_ms;
}

export function clearHeartbeat(db: DatabaseSync, name: string): void {
  db.prepare('DELETE FROM heartbeats WHERE name = ?').run(name);
}

