import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  MAX_ATTEMPTS,
  RETRY_DELAY_MS,
  recordProgress,
  recoverInterruptedJobs,
  requeueJob,
  STEP_MS,
  TRANSIENT_ERROR,
  writeHeartbeat,
  type JobView,
} from './jobs.ts';

const HEARTBEAT_MS = 1000;
const POLL_MS = 200;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/**
 * Runs one attempt of a claimed job. Each step takes STEP_MS and records progress. Attempt n fails
 * at its first step, before any progress, while n <= failAttempts; the third failure is terminal.
 * If shutdown is requested mid-attempt, the job goes back to the queue at once.
 */
async function runAttempt(job: JobView): Promise<void> {
  const interrupted = (): boolean => stopping;

  if (job.attempts <= job.failAttempts) {
    await sleep(STEP_MS);
    if (interrupted()) return requeueJob(db, job.id, 0);
    if (job.attempts >= MAX_ATTEMPTS) failJob(db, job.id, TRANSIENT_ERROR);
    else requeueJob(db, job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let completed = 1; completed <= job.steps; completed++) {
    await sleep(STEP_MS);
    if (interrupted()) return requeueJob(db, job.id, 0);
    recordProgress(db, job.id, completed);
  }
  completeJob(db, job.id, job.input.toUpperCase(), job.steps);
}

const recovered = recoverInterruptedJobs(db);
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);

const beat = (): void => writeHeartbeat(db, 'worker', Date.now());
beat();
const heartbeatTimer = setInterval(() => {
  try {
    beat();
  } catch (e) {
    console.error('heartbeat failed:', e instanceof Error ? e.message : e);
  }
}, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNextJob(db, Date.now());
    if (!job) {
      await sleep(POLL_MS);
      continue;
    }
    await runAttempt(job);
  } catch (e) {
    console.error('worker error:', e instanceof Error ? e.message : e);
    await sleep(1000);
  }
}

clearInterval(heartbeatTimer);
clearHeartbeat(db, 'worker');
db.close();
console.log('worker stopped');

